    cols = len(grid[0])
    bg_color = grid[0][0]

    color_counts = {}
    for r in range(rows):
        for c in range(cols):
            color_counts[grid[r][c]] = color_counts.get(grid[r][c], 0) + 1

    colors_without_bg = {k: v for k, v in color_counts.items() if k != bg_color}
    if colors_without_bg:
        bar_color = max(colors_without_bg, key=colors_without_bg.get)
    else:
        bar_color = 2

    bar_cells = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == bar_color]

    bar_rows = sorted(set(r for r, c in bar_cells))
    top_r = bar_rows[0]
    bot_r = bar_rows[-1]

    # Bottom bar rightmost column
    bot_line_col = sorted([c for r, c in bar_cells if r == bot_r[-1]])[-1] if bar_cells else 0
    top_start = sorted([c for r, c in bar_cells if r == top_r])[0] if bar_cells else 0

    output = [[bg_color for _ in range(cols)] for _ in range(rows)]

    for r, c in bar_cells:
        output[r][c] = bar_color

    sources = [(r, c, grid[r][c]) for r in range(rows) for c in range(cols)
               if grid[r][c] != bg_color and grid[r][c] != bar_color]

    for r_s, c_s, sc in sources:
        # Target column = bottom bar's rightmost column
        target_col = bot_line_col

        # Draw vertical line at target_col
        for r in range(top_r, bot_r):
            if 0 <= target_col < cols:
                output[r][target_col] = sc

        # Gap fill at source column
        if r_s > top_r:
            for r in range(top_r + 1, r_s):
                output[r][c_s] = sc

        # Update source
        output[r_s][c_s] = sc + 3

    return output
