    bg = grid[0][0]

    # Find bar color - most frequent non-background color
    cnts = {}
    for r in range(h):
        for c in range(w):
            cnts[grid[r][c]] = cnts.get(grid[r][c], 0) + 1

    non_bg = [k for k in cnts.keys() if k != bg]
    if non_bg:
        bar_color = max(non_bg, key=cnts.get)
    else:
        bar_color = 2

    # Find all bar cells
    bar_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == bar_color]

    if not bar_cells:
        return grid

    # Get bar rows
    bar_rows = sorted(set(r for r, c in bar_cells))
    top_r = bar_rows[0]
    bot_r = bar_rows[-1]

    # Get top bar start column
    top_cols = [c for r, c in bar_cells if r == top_r]
    top_start = min(top_cols)

    # Build output grid
    out = [[bg for _ in range(w)] for _ in range(h)]

    # Place bars
    for r, c in bar_cells:
        out[r][c] = bar_color

    # Find source pixels
    sources = []
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != bg and v != bar_color:
                sources.append((r, c, v))

    # Process each source
    for rs, cs, sc in sources:
        # Target column for vertical line
        target = cs - top_start

        # Draw vertical line
        if 0 <= target < w:
            for r in range(top_r, bot_r):
                out[r][target] = sc

        # Fill gap from top bar to source
        if rs > top_r:
            for r in range(top_r + 1, rs):
                out[r][cs] = sc

        # Transform source pixel
        out[rs][cs] = sc + 3

    return out
